"use client";

import { loadFont } from "@remotion/google-fonts/Figtree";
import type React from "react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  interpolateColors,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_TEXT,
  type StoryTextElementId,
  storyTextTimeline,
  storyWords,
} from "./timeline";

const figtree = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const sans = figtree.fontFamily;

export interface StoryTextProps {
  text?: string;
  measure?: number;
  accent?: string;
  /** Text and sticker color; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the text. Load it yourself; Figtree by default. */
  fontFamily?: string;
  /** Frames between words as they type in. */
  stagger?: number;
  /** Frames the typed text holds before the sticker styles cycle. */
  hold?: number;
  /** Size of the sticker, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  speed?: number;
  /**
   * Moves, trims or stretches each word, the caret, the sticker styles and
   * the ground's push, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<StoryTextElementId>;
}

const FONT_PX = 100;
const TRACK = -0.012;

const ENTER = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "mist",
  background: "#F2EDE6",
  colors: ["#F58C3D", "#F7C79B", "#E889B5", "#FFF6EC"],
};

const THEMES = {
  dark: {
    ground: "static-sunset" as GshPresetId,
    base: "#0A0510",
    fg: "#FBF7F1",
    sticker: "#FBF7F1",
    onFill: "#17120E",
    scrim: "10,5,16",
    scrimA: 0.34,
    lift: "rgba(20,6,12,0.38)",
    shadow: "0 2px 22px rgba(10,5,16,0.45)",
  },
  light: {
    ground: undefined,
    base: "#F2EDE6",
    fg: "#17140F",
    sticker: "#17140F",
    onFill: "#FBF7F1",
    scrim: "242,237,230",
    scrimA: 0.3,
    lift: "rgba(80,40,20,0.22)",
    shadow: "0 1px 16px rgba(242,237,230,0.6)",
  },
} as const;

function measureWith(_version: number, family: string) {
  const ctx = document.createElement("canvas").getContext("2d");
  const cache: Record<string, number> = {};
  return (s: string) => {
    if (cache[s] === undefined) {
      if (!ctx) return s.length * 0.52;
      ctx.font = `400 ${FONT_PX}px "${family}"`;
      cache[s] = ctx.measureText(s).width / FONT_PX + TRACK * [...s].length;
    }
    return cache[s];
  };
}

function useMeasure(family: string) {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("story-text: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      figtree.waitUntilDone(),
      document.fonts.load(`400 ${FONT_PX}px "${family}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle, family]);
  return useMemo(() => measureWith(version, family), [version, family]);
}

function wrap(widths: number[], space: number, max: number) {
  const lineOf: number[] = [];
  let line = 0;
  let run = 0;
  widths.forEach((w, i) => {
    const next = run === 0 ? w : run + space + w;
    if (run > 0 && next > max) {
      line += 1;
      run = w;
    } else {
      run = next;
    }
    lineOf[i] = line;
  });
  return lineOf;
}

type Pt = [number, number];

function roundedPath(raw: Pt[], R: number) {
  const pts: Pt[] = [];
  for (const p of raw) {
    const q = pts[pts.length - 1];
    if (!q || Math.hypot(p[0] - q[0], p[1] - q[1]) > 0.25) pts.push(p);
  }
  if (pts.length > 1) {
    const a = pts[0];
    const b = pts[pts.length - 1];
    if (Math.hypot(a[0] - b[0], a[1] - b[1]) <= 0.25) pts.pop();
  }
  const clean = pts.filter((v, i) => {
    const p = pts[(i - 1 + pts.length) % pts.length];
    const n = pts[(i + 1) % pts.length];
    const cross = (v[0] - p[0]) * (n[1] - v[1]) - (v[1] - p[1]) * (n[0] - v[0]);
    return Math.abs(cross) > 0.01;
  });
  const N = clean.length;
  if (N < 3) return "";
  let d = "";
  clean.forEach((v, i) => {
    const p = clean[(i - 1 + N) % N];
    const n = clean[(i + 1) % N];
    const lin = Math.hypot(v[0] - p[0], v[1] - p[1]);
    const lout = Math.hypot(n[0] - v[0], n[1] - v[1]);
    const r = Math.min(R, lin / 2, lout / 2);
    const a: Pt = [
      v[0] + ((p[0] - v[0]) / lin) * r,
      v[1] + ((p[1] - v[1]) / lin) * r,
    ];
    const b: Pt = [
      v[0] + ((n[0] - v[0]) / lout) * r,
      v[1] + ((n[1] - v[1]) / lout) * r,
    ];
    const cross = (v[0] - p[0]) * (n[1] - v[1]) - (v[1] - p[1]) * (n[0] - v[0]);
    const sweep = cross > 0 ? 1 : 0;
    d += `${i === 0 ? "M" : "L"}${a[0].toFixed(2)} ${a[1].toFixed(2)}`;
    d += `A${r.toFixed(2)} ${r.toFixed(2)} 0 0 ${sweep} ${b[0].toFixed(2)} ${b[1].toFixed(2)}`;
  });
  return `${d}Z`;
}

// The word ramps are clamped, so exactly 0 or 1 at rest; the ease-out's last
// frame still moves a word by a hundredth of a pixel, so it counts.
const midway = (p: number) => p > 0 && p < 1;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function StoryText(props: StoryTextProps) {
  const {
    text = DEFAULT_TEXT,
    measure,
    accent = "#3B5BFD",
    ink: inkColor,
    background,
    fontFamily = sans,
    scale = 1,
    delay = 0,
    theme = "dark",
    ground,
    groundParams,
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    storyTextTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const t = THEMES[theme];
  const fg = inkColor ?? t.fg;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const width = useMeasure(fontFamily);
  const tall = H > W;

  const words = storyWords(text);
  const F = tall ? W * 0.115 : H * 0.125;
  const space = width(" ");
  const widths = words.map((w) => width(w));
  const lineOf = wrap(
    widths,
    space,
    (W * (measure ?? (tall ? 0.8 : 0.76))) / F,
  );
  const lineCount = (lineOf[lineOf.length - 1] ?? 0) + 1;

  const lh = F * 1.34;
  const padX = F * 0.36;
  const R = lh * 0.3;

  const wordEls = words.map((_, i) => tl.get(`word:${i}`));
  const appear = wordEls.map((e) =>
    Math.max(
      0,
      spring({
        frame: frame - e.start,
        fps,
        config: CARD,
      }),
    ),
  );
  const ink = wordEls.map((e) =>
    interpolate(frame, [e.start + e.beat("ink"), e.end + 1], [0, 1], {
      ...CLAMP,
      easing: ENTER,
    }),
  );
  const caretEl = tl.get("caret");

  const fillEl = tl.get("fill");
  const C3 = fillEl.start;
  const step = (e: { start: number; end: number }) =>
    interpolate(frame, [e.start, e.end], [0, 1], { ...CLAMP, easing: MOVE });
  const toOutline = step(tl.get("outline"));
  const toNone = step(tl.get("clear"));
  const toFill = step(fillEl);
  const fillAmt = 1 - toOutline + toFill;
  const strokeAmt = toOutline * (1 - toNone);
  const textColor = interpolateColors(fillAmt, [0, 1], [fg, t.onFill]);
  const settleAt = (f: number) =>
    f >= C3
      ? 1 +
        0.035 *
          Math.sin(
            Math.min(1, spring({ frame: f - C3, fps, config: CARD })) * Math.PI,
          )
      : 1;
  const settle = settleAt(frame);
  // The pop is a spring, so it has no clean end: compare the scale with the
  // neighbouring frames, weighed by the reach from the centre to the far text.
  const reach = Math.max(W, H) / 2;
  const settling =
    Math.abs(settleAt(frame + speed) - settle) * reach > 1e-3 ||
    Math.abs(settle - settleAt(frame - speed)) * reach > 1e-3;

  const lines = Array.from({ length: lineCount }, (_, l) => {
    const idx = words.map((_, i) => i).filter((i) => lineOf[i] === l);
    let w = 0;
    const xs: number[] = [];
    idx.forEach((i, k) => {
      const a = appear[i];
      if (k > 0) w += space * F * Math.min(1, a * 3);
      xs.push(w);
      w += widths[i] * F * a;
    });
    const grow = appear[idx[0]] ?? 0;
    return { idx, xs, w, grow };
  });
  const lineH = (g: number) => lh * MOVE(Math.min(1, g * 1.6));
  const totalH = lines.reduce((acc, l) => acc + lineH(l.grow), 0);
  let y = H / 2 - totalH / 2;
  const geo = lines.map((l) => {
    const h = lineH(l.grow);
    const top = y;
    y += h;
    const half = l.w / 2 + padX * Math.min(1, l.grow * 2);
    return { ...l, top, h, x0: W / 2 - half, x1: W / 2 + half };
  });
  const shown = geo.filter((g) => g.h > 0.5 && g.x1 - g.x0 > 1);

  let path = "";
  if (shown.length) {
    const pts: Pt[] = [];
    const first = shown[0];
    pts.push([first.x0, first.top], [first.x1, first.top]);
    shown.forEach((g, i) => {
      pts.push([g.x1, g.top + g.h]);
      const next = shown[i + 1];
      if (next) pts.push([next.x1, g.top + g.h]);
    });
    const last = shown[shown.length - 1];
    pts.push([last.x0, last.top + last.h]);
    for (let i = shown.length - 1; i > 0; i--) {
      pts.push([shown[i].x0, shown[i].top], [shown[i - 1].x0, shown[i].top]);
    }
    path = roundedPath(pts, R);
  }

  const caretOpacity = interpolate(
    frame,
    [
      caretEl.start + caretEl.beat("fadeAt"),
      caretEl.start + caretEl.beat("fadeEnd"),
    ],
    [1, 0],
    { ...CLAMP, easing: EXIT },
  );
  let caret: { x: number; top: number } | null = null;
  for (let i = words.length - 1; i >= 0; i--) {
    if (appear[i] > 0 || i === 0) {
      const g = geo[lineOf[i]];
      const k = g.idx.indexOf(i);
      caret = {
        x: W / 2 - g.w / 2 + g.xs[k] + widths[i] * F * appear[i] + F * 0.06,
        top: g.top + (lh - F * 1.08) / 2,
      };
      break;
    }
  }

  const pushEl = tl.get("push");
  const push = interpolate(frame, [pushEl.start, pushEl.end], [1, 1.04], CLAMP);

  return (
    <AbsoluteFill
      style={{
        background: background === undefined ? t.base : undefined,
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          <AbsoluteFill style={{ transform: `scale(${push})` }}>
            <GshGround
              preset={groundParams ? undefined : (ground ?? t.ground)}
              params={
                groundParams ??
                (theme === "light" && !ground ? LIGHT_GROUND : undefined)
              }
              timeOffset={theme === "dark" ? 3 : 5}
              timeScale={0.4}
            />
          </AbsoluteFill>
          <AbsoluteFill
            style={{
              background: `radial-gradient(${tall ? "90% 40%" : "60% 55%"} at 50% 50%, rgba(${t.scrim},${t.scrimA}) 0%, rgba(${t.scrim},0) 100%)`,
            }}
          />
        </>
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${settle})${glide(settling)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            aria-hidden
          >
            {path ? (
              <>
                <defs>
                  <filter
                    id={`${uid}-lift`}
                    x="-20%"
                    y="-40%"
                    width="140%"
                    height="180%"
                  >
                    <feDropShadow
                      dx="0"
                      dy={F * 0.12}
                      stdDeviation={F * 0.22}
                      floodColor={t.lift}
                    />
                  </filter>
                </defs>
                <path
                  d={path}
                  fill={inkColor ?? t.sticker}
                  opacity={Math.min(1, fillAmt)}
                  filter={`url(#${uid}-lift)`}
                />
                <path
                  d={path}
                  fill="none"
                  stroke={fg}
                  strokeWidth={Math.max(2, F * 0.045)}
                  opacity={strokeAmt}
                />
              </>
            ) : null}
          </svg>
          <div
            style={{
              position: "absolute",
              inset: 0,
              fontFamily,
              fontWeight: 400,
              clipPath: path ? `path("${path}")` : undefined,
            }}
          >
            {geo.map((g) =>
              g.idx.map((i, k) => {
                const a = ink[i];
                if (a <= 0) return null;
                return (
                  <span
                    key={`w-${i}`}
                    style={{
                      position: "absolute",
                      left: W / 2 - g.w / 2 + g.xs[k],
                      top: g.top + (lh - F) / 2,
                      fontSize: F,
                      lineHeight: 1,
                      letterSpacing: `${TRACK}em`,
                      whiteSpace: "pre",
                      color: textColor,
                      textShadow: fillAmt < 0.5 ? t.shadow : undefined,
                      opacity: a,
                      transformOrigin: "0% 80%",
                      transform: `translateY(${(1 - a) * F * 0.22}px) scale(${0.9 + 0.1 * a})${glide(midway(a) && !settling)}`,
                    }}
                  >
                    {words[i]}
                  </span>
                );
              }),
            )}
            {caret ? (
              <div
                style={{
                  position: "absolute",
                  // Layout rounds a box's edges to whole pixels, so a caret
                  // carried by `left`/`top` steps; it rides a transform.
                  left: 0,
                  top: 0,
                  transform: `translate(${caret.x}px, ${caret.top}px)`,
                  width: Math.max(2, F * 0.045),
                  height: F * 1.08,
                  borderRadius: F,
                  background: accent,
                  opacity: caretOpacity,
                }}
              />
            ) : null}
          </div>
        </AbsoluteFill>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The words typing into the sticker one by one, the caret fading once the
// last word lands, then the sticker cycling from fill to outline to clear and
// back to fill with a pop. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. The ids are public: a saved `timing` prop refers to
// them.

export type StoryTextElementId =
  | `word:${number}`
  | "push"
  | "caret"
  | "outline"
  | "clear"
  | "fill";

export interface StoryTextTimingProps {
  text?: string;
  /** Frames between words as they type in. */
  stagger?: number;
  /** Frames the typed text holds before the sticker styles cycle. */
  hold?: number;
}

export const DEFAULT_TEXT =
  "okay, it’s live — the update you kept asking for is finally here";
const FIRST_WORD = -2;
export const WORD_GAP = 5;
const WORD_IN = 8;
const HOLD = 14;
/** Frames between one sticker style and the next. */
const STYLE_GAP = 22;
/** Frames one sticker style takes to blend in. */
const STYLE_IN = 9;

/** The text as words, split on whitespace. */
export function storyWords(text: string) {
  return text.split(/\s+/).filter(Boolean);
}

// `word:<i>` springs in at its start and inks in from `ink` to two frames
// past its end; the list is a chain. `caret` starts when the last word has
// landed and fades from `fadeAt` to `fadeEnd`. `outline`, `clear` and
// `fill` each blend the sticker into the next style; `fill` also pops the
// sticker. `push` is the slow push on the ground.
export const storyTextTimeline = defineTimeline<
  StoryTextElementId,
  StoryTextTimingProps
>(({ text = DEFAULT_TEXT, stagger = WORD_GAP, hold = HOLD }) => {
  const words = storyWords(text);
  const elements: TimelineElement<StoryTextElementId>[] = words.map(
    (word, i) => ({
      id: `word:${i}`,
      lane: "Words",
      label: word,
      start: FIRST_WORD + i * stagger,
      length: WORD_IN,
      follows: i > 0 ? `word:${i - 1}` : undefined,
      beats: { ink: 2 },
    }),
  );
  elements.push({
    id: "push",
    lane: "Ground",
    label: "push",
    start: 0,
    length: 200,
  });
  const typedEnd = FIRST_WORD + (words.length - 1) * stagger + WORD_IN;
  const last = words.length ? (`word:${words.length - 1}` as const) : undefined;
  const C1 = typedEnd + hold;
  const C2 = C1 + STYLE_GAP;
  const C3 = C2 + STYLE_GAP;
  elements.push(
    {
      id: "caret",
      lane: "Caret",
      label: "caret",
      start: typedEnd,
      length: 6,
      follows: last,
      beats: { fadeAt: -2, fadeEnd: 6 },
    },
    {
      id: "outline",
      lane: "Sticker",
      label: "outline",
      start: C1,
      length: STYLE_IN,
      follows: last,
    },
    {
      id: "clear",
      lane: "Sticker",
      label: "clear",
      start: C2,
      length: STYLE_IN,
      follows: "outline",
    },
    {
      id: "fill",
      lane: "Sticker",
      label: "fill",
      start: C3,
      length: STYLE_IN,
      follows: "clear",
    },
  );
  return elements.sort((a, b) => a.start - b.start);
});
